#!/usr/bin/env python3
import json
import os
import sys
from pathlib import Path
from datetime import datetime, timezone, timedelta
import re
import subprocess

BRAIN_DIR = Path.home() / ".gemini/antigravity/brain"
WORKSPACE_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-workspace")
PLUGIN_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-plugin")
SIDECAR_DIR = Path.home() / ".gemini/antigravity/sidecar_data"

now = datetime.now(timezone.utc)
cutoff_24h = now - timedelta(hours=24)

# 1. First, parse the sidecar logs for high-level events
sidecar_logs = {
    "engineering": SIDECAR_DIR / "bug-fixer-engineering-loop--esp32-app-foundation/logs/sidecar.log",
    "pr_review": SIDECAR_DIR / "bug-fixer-pr-review-loop--esp32-app-foundation/logs/sidecar.log",
    "triage": SIDECAR_DIR / "bug-fixer-triage-loop--esp32-app-foundation/logs/sidecar.log",
    "trajectory": SIDECAR_DIR / "bug-fixer-trajectory-loop--esp32-app-foundation/logs/sidecar.log",
}

print("=== SIDECAR LOGS SUMMARY ===")
for name, path in sidecar_logs.items():
    if path.exists():
        lines = path.read_text(errors="replace").splitlines()
        recent = [l for l in lines if l.strip()]
        print(f"[{name}] {path.name}: {len(lines)} total lines")
        # Print last 10 lines
        for l in recent[-10:]:
            print(f"   {l}")
    else:
        print(f"[{name}] Not found: {path}")

# 2. Gather conversation details
print("\n=== CONVERSATIONS ANALYSIS ===")

conv_dirs = []
for cdir in BRAIN_DIR.iterdir():
    if not cdir.is_dir():
        continue
    tpath = cdir / ".system_generated/logs/transcript.jsonl"
    if not tpath.exists():
        continue
    mtime = datetime.fromtimestamp(tpath.stat().st_mtime, tz=timezone.utc)
    if mtime < cutoff_24h:
        continue
    conv_dirs.append((mtime, cdir.name, tpath))

conv_dirs.sort(key=lambda x: x[0], reverse=True)

parsed_convs = []

for mtime, cid, tpath in conv_dirs:
    # Read transcript
    user_prompt = ""
    agent_type = "unknown"
    issue_num = None
    pr_num = None
    steps = 0
    tools_called = []
    tests_run = []
    test_failures = []
    errors = []
    exit_status = "in_progress"
    final_text = ""
    first_ts = None
    last_ts = None

    try:
        with open(tpath, "r", encoding="utf-8", errors="replace") as f:
            for line_idx, line in enumerate(f):
                line = line.strip()
                if not line:
                    continue
                try:
                    step = json.loads(line)
                except Exception:
                    continue
                steps += 1
                ts_str = step.get("created_at")
                if ts_str:
                    if first_ts is None:
                        first_ts = ts_str
                    last_ts = ts_str

                stype = step.get("type")
                source = step.get("source")
                content = step.get("content") or ""

                if stype == "USER_INPUT" or (source == "USER_EXPLICIT" and not user_prompt):
                    if not user_prompt:
                        user_prompt = content[:2000]

                # Check tool calls
                tc_list = step.get("tool_calls") or []
                for tc in tc_list:
                    tname = tc.get("name") or (tc.get("function", {}).get("name") if isinstance(tc.get("function"), dict) else "")
                    args = tc.get("args") or tc.get("arguments") or {}
                    if isinstance(args, str):
                        try:
                            args = json.loads(args)
                        except:
                            pass
                    tools_called.append(tname)

                    if tname in ("run_command", "runPersistentCommand", "runBashCommand"):
                        cmd = args.get("CommandLine", "") or args.get("command", "")
                        if "pio test" in cmd or "run_tests" in cmd or "ctest" in cmd:
                            tests_run.append(cmd)
                        if "gh pr create" in cmd:
                            exit_status = "pr_created"
                        if "ENGINEERING_EXIT" in cmd:
                            exit_status = "exited"

                # Check for test results in content
                if "test" in content.lower():
                    if "FAILED" in content or "FAILURE" in content or "Assertion failed" in content:
                        for fail_line in content.splitlines():
                            if any(k in fail_line for k in ["FAILED", "FAILURE", "Assertion", "FAIL:"]):
                                test_failures.append(fail_line[:120])

                if stype == "PLANNER_RESPONSE":
                    final_text = content

    except Exception as e:
        print(f"Error reading {cid}: {e}")
        continue

    # Classify agent_type
    prompt_lower = user_prompt.lower()
    if "bug-fixer-triage" in prompt_lower or "triage open issues" in prompt_lower or "triage:" in prompt_lower:
        agent_type = "triage"
    elif "bug-fixer-engineering" in prompt_lower or "fix #" in prompt_lower or "engineering_dispatcher" in prompt_lower:
        agent_type = "engineering"
    elif "pr_iteration" in prompt_lower or "review pr" in prompt_lower or "needs-iteration" in prompt_lower:
        agent_type = "pr_iteration"
    elif "bug-fixer-trajectory" in prompt_lower or "trajectory review" in prompt_lower:
        agent_type = "trajectory_review"
    else:
        # Check if relevant
        if not any(k in prompt_lower for k in ["bug-fixer", "esp32-app-foundation", "auto-fixable", "safe_ingest"]):
            continue

    # Extract issue or PR num
    m_issue = re.search(r"Fix #(\d+)|issue #?(\d+)|Issue (\d+)", user_prompt, re.IGNORECASE)
    if m_issue:
        issue_num = next(g for g in m_issue.groups() if g)

    m_pr = re.search(r"PR #?(\d+)|pull/(\d+)", user_prompt, re.IGNORECASE)
    if m_pr:
        pr_num = next(g for g in m_pr.groups() if g)

    # Check resolution from final_text
    if "ENGINEERING_EXIT" in final_text:
        exit_status = "exited"
        m_exit = re.search(r"ENGINEERING_EXIT:?\s*([^\n\r]+)", final_text)
        if m_exit:
            exit_status = f"exited: {m_exit.group(1)[:60]}"
    elif "PR created" in final_text or "Created PR" in final_text or "pull request" in final_text.lower():
        if "opened" in final_text.lower() or "created" in final_text.lower() or exit_status == "pr_created":
            exit_status = "pr_created"

    parsed_convs.append({
        "cid": cid,
        "mtime": mtime.isoformat(),
        "first_ts": first_ts,
        "last_ts": last_ts,
        "type": agent_type,
        "issue": issue_num,
        "pr": pr_num,
        "steps": steps,
        "tests_count": len(tests_run),
        "test_failures_count": len(test_failures),
        "failures_sample": test_failures[:5],
        "exit_status": exit_status,
        "prompt_head": user_prompt.replace("\n", " ")[:150],
        "final_snippet": final_text.replace("\n", " ")[:200],
    })

print(f"Total classified bug-fixer conversations: {len(parsed_convs)}")
types_count = {}
for c in parsed_convs:
    types_count[c["type"]] = types_count.get(c["type"], 0) + 1
print(f"Breakdown by type: {types_count}")

# Save detailed dump
dump_path = WORKSPACE_DIR / "tmp/conversations_summary.json"
dump_path.write_text(json.dumps(parsed_convs, indent=2))
print(f"Saved summary to {dump_path}")

for c in parsed_convs:
    print(f"- [{c['type'].upper()}] Issue #{c['issue']} PR #{c['pr']} | Status: {c['exit_status']} | Steps: {c['steps']} | CID: {c['cid']}")
    if c['failures_sample']:
        print(f"    Failures: {c['failures_sample'][:2]}")

#!/usr/bin/env python3
import json
import os
import sys
from pathlib import Path
import subprocess

SCRIPT_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-plugin/scripts")
SAFE_INGEST = SCRIPT_DIR / "safe_ingest.py"
REPO = "matthewmcneill/esp32-app-foundation"

def run_safe_ingest(subcmd, *args):
    cmd = ["python3", str(SAFE_INGEST), subcmd, "--repo", REPO, *args]
    res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode != 0:
        print(f"Error running {cmd}: {res.stderr}")
        return None
    try:
        return json.loads(res.stdout)
    except:
        return res.stdout

print("=== CHECKING RECENT PRS ===")
prs = run_safe_ingest("pr-list", "--limit", "40", "--state", "all")
if isinstance(prs, list):
    print(f"Fetched {len(prs)} PRs:")
    for p in prs:
        labels = [l.get("name") if isinstance(l, dict) else str(l) for l in p.get("labels", [])]
        print(f"PR #{p.get('number')} [{p.get('state')}] {p.get('title')} (labels: {', '.join(labels)}) created: {p.get('createdAt')}")

print("\n=== CHECKING OPEN ISSUES ===")
issues = run_safe_ingest("issue-list", "--limit", "40", "--state", "open")
if isinstance(issues, list):
    print(f"Fetched {len(issues)} open issues:")
    for iss in issues:
        labels = [l.get("name") if isinstance(l, dict) else str(l) for l in iss.get("labels", [])]
        print(f"Issue #{iss.get('number')} [{iss.get('state')}] {iss.get('title')} (labels: {', '.join(labels)})")

print("\n=== CHECKING CLOSED ISSUES (RECENT) ===")
closed_issues = run_safe_ingest("issue-list", "--limit", "30", "--state", "closed")
if isinstance(closed_issues, list):
    print(f"Fetched {len(closed_issues)} recently closed issues:")
    for iss in closed_issues:
        labels = [l.get("name") if isinstance(l, dict) else str(l) for l in iss.get("labels", [])]
        print(f"Issue #{iss.get('number')} [{iss.get('state')}] {iss.get('title')} (labels: {', '.join(labels)}) closed: {iss.get('updatedAt')}")

