        continue

    conv_data["first_ts"] = steps[0].get("created_at")
    conv_data["last_ts"] = steps[-1].get("created_at")

    # Find initial user prompt
    for s in steps:
        if s.get("type") == "USER_INPUT" or (s.get("source") == "USER_EXPLICIT" and not conv_data["user_prompt"]):
            conv_data["user_prompt"] = s.get("content", "")
            break

    prompt = conv_data["user_prompt"]
    prompt_l = prompt.lower()

    if "bug-fixer-triage" in prompt_l or "triage open issues" in prompt_l or "triage:" in prompt_l:
        conv_data["task_type"] = "triage"
    elif "pr_iteration" in prompt_l or "needs-iteration" in prompt_l or "review pr" in prompt_l or "iterate on pr" in prompt_l:
        conv_data["task_type"] = "pr_iteration"
    elif "bug-fixer-engineering" in prompt_l or "fix #" in prompt_l or "engineering_dispatcher" in prompt_l:
