    elif "trajectory" in prompt_l:
        conv_data["task_type"] = "trajectory_review"

    m_iss = re.search(r"Fix #(\d+)|issue #?(\d+)|Issue (\d+)", prompt, re.IGNORECASE)
    if m_iss:
        conv_data["target_issue"] = next(g for g in m_iss.groups() if g)

    m_pr = re.search(r"PR #?(\d+)|pull/(\d+)", prompt, re.IGNORECASE)
    if m_pr:
        conv_data["target_pr"] = next(g for g in m_pr.groups() if g)

    # Process all steps
    last_planner_step = None
    for idx, s in enumerate(steps):
        stype = s.get("type")
        content = s.get("content") or ""
        tcalls = s.get("tool_calls") or []

        if stype == "PLANNER_RESPONSE":
            last_planner_step = s

        for tc in tcalls:
            tname = tc.get("name") or (tc.get("function", {}).get("name") if isinstance(tc.get("function"), dict) else "")
            args = tc.get("args") or tc.get("arguments") or {}
            if isinstance(args, str):
                try:
                    args = json.loads(args)
                except:
                    pass

