                cmd = args.get("CommandLine", "")
                conv_data["commands_run"].append(cmd[:120])
                if "checkout -b" in cmd:
                    conv_data["git_branches"].append(cmd)
                if "git commit" in cmd:
                    conv_data["git_commits"].append(cmd[:100])
                if "gh pr create" in cmd:
                    conv_data["prs_created"].append(cmd)
                if "pio test" in cmd or "run_tests" in cmd:
                    conv_data["test_runs"].append({"type": "cmd", "cmd": cmd[:80]})

            elif tname == "call_mcp_tool":
                tool = args.get("ToolName", "")
                server = args.get("ServerName", "")
                if "test" in tool.lower() or "build" in tool.lower() or "lock" in tool.lower():
                    conv_data["commands_run"].append(f"MCP:{server}:{tool}")
                if "run_tests" in tool:
                    conv_data["test_runs"].append({"type": "mcp", "tool": tool})
                if "acquire_lock" in tool or "release_lock" in tool or "get_lock" in tool:
                    conv_data["lock_contention"].append(f"MCP:{tool}")

        # Check content for issues
        if "lock held" in content.lower() or "resource busy" in content.lower():
            conv_data["lock_contention"].append(content[:150])

        if "dirty working tree" in content.lower() or "working tree is dirty" in content.lower():
            conv_data["dirty_tree_issues"].append(content[:150])

        if "compilation error" in content.lower() or "error: " in content:
            # find compilation errors
            for l in content.splitlines():
                if "error:" in l and "safe_ingest" not in l and "sys.stderr" not in l:
                    conv_data["build_errors"].append(l[:140])

        if "FAILED" in content or "FAILURE" in content:
            for l in content.splitlines():
                if any(k in l for k in ["FAIL:", "FAILED", "Assertion failed", "Failure"]):
                    if len(l.strip()) > 5:
                        conv_data["test_failures"].append(l.strip()[:140])

        if "ENGINEERING_EXIT" in content:
            m_exit = re.search(r"ENGINEERING_EXIT:?\s*([^\n\r]+)", content)
            if m_exit:
                conv_data["exit_reason"] = m_exit.group(1).strip()

    if last_planner_step:
        conv_data["final_message"] = (last_planner_step.get("content") or "")[:500]
        # Stall check: last step is PLANNER_RESPONSE with no tool calls and asking a question
        if not last_planner_step.get("tool_calls"):
            fm = conv_data["final_message"].lower()
            if any(q in fm for q in ["shall i", "would you like", "let me know", "please confirm", "do you want", "waiting for"]):
                conv_data["stall_detected"] = True

    results.append(conv_data)

# Print a structured report for all 20
out_file = WORKSPACE_DIR / "tmp/twenty_transcripts_analysis.json"
out_file.write_text(json.dumps(results, indent=2))
print(f"Saved deep analysis of 20 transcripts to {out_file}")

for r in results:
    dur = "unknown"
    if r.get("first_ts") and r.get("last_ts"):
        try:
            t0 = datetime.fromisoformat(r["first_ts"].replace("Z", "+00:00"))
            t1 = datetime.fromisoformat(r["last_ts"].replace("Z", "+00:00"))
            dur = f"{(t1 - t0).total_seconds()/60:.1f}m"
        except:
            pass

    print(f"\n[{r['task_type'].upper()}] CID: {r['cid']} | Dur: {dur} | Steps: {r['steps_count']}")
    print(f"  Target: Issue #{r['target_issue']} | PR #{r['target_pr']}")
    print(f"  PRs Created: {len(r['prs_created'])} | Commits: {len(r['git_commits'])} | Tests run: {len(r['test_runs'])}")
    if r['exit_reason']:
        print(f"  Exit Reason: {r['exit_reason']}")
    if r['stall_detected']:
        print(f"  ⚠️ Stall Detected: ended asking user")
    if r['build_errors']:
        print(f"  Build errors ({len(r['build_errors'])}): {r['build_errors'][:2]}")
    if r['test_failures']:
        print(f"  Test failures ({len(r['test_failures'])}): {r['test_failures'][:2]}")
    if r['lock_contention']:
        print(f"  Lock contention events: {len(r['lock_contention'])}")
    if r['dirty_tree_issues']:
        print(f"  Dirty tree issues: {len(r['dirty_tree_issues'])}")

