#!/usr/bin/env python3
import json
import subprocess
from datetime import datetime, timezone, timedelta
from pathlib import Path

SCRIPT_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-plugin/scripts")
SAFE_INGEST = SCRIPT_DIR / "safe_ingest.py"
REPO = "matthewmcneill/esp32-app-foundation"

now = datetime.now(timezone.utc)
cutoff_24h = now - timedelta(hours=24)

def run_ingest(subcmd, *args):
    cmd = ["python3", str(SAFE_INGEST), subcmd, "--repo", REPO, *args]
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0:
        return None
    try:
        return json.loads(r.stdout)
    except:
        return None

prs = run_ingest("pr-list", "--limit", "30", "--state", "all")

opened_24h = []
merged_24h = []
closed_unmerged_24h = []

for p in prs:
    c_ts = p.get("createdAt")
    m_ts = p.get("mergedAt")
    cl_ts = p.get("closedAt")

    if c_ts:
        c_dt = datetime.fromisoformat(c_ts.replace("Z", "+00:00"))
        if c_dt >= cutoff_24h:
            opened_24h.append(p)

    if m_ts:
        m_dt = datetime.fromisoformat(m_ts.replace("Z", "+00:00"))
        if m_dt >= cutoff_24h:
            merged_24h.append(p)
    elif cl_ts:
        cl_dt = datetime.fromisoformat(cl_ts.replace("Z", "+00:00"))
        if cl_dt >= cutoff_24h:
            closed_unmerged_24h.append(p)

print(f"=== METRICS IN LAST 24H ({cutoff_24h.isoformat()} to {now.isoformat()}) ===")
print(f"PRs Opened: {len(opened_24h)}")
for p in opened_24h:
    print(f"  PR #{p['number']} [{p['state']}] {p['title']} (created {p['createdAt']})")

print(f"\nPRs Merged: {len(merged_24h)}")
for p in merged_24h:
    print(f"  PR #{p['number']} {p['title']} (merged {p.get('mergedAt')})")

print(f"\nPRs Closed/Rejected: {len(closed_unmerged_24h)}")

# Compare with previous day (24-48h ago)
cutoff_48h = cutoff_24h - timedelta(hours=24)
opened_prev = []
merged_prev = []

for p in prs:
    c_ts = p.get("createdAt")
    m_ts = p.get("mergedAt")
    if c_ts:
        c_dt = datetime.fromisoformat(c_ts.replace("Z", "+00:00"))
        if cutoff_48h <= c_dt < cutoff_24h:
            opened_prev.append(p)
    if m_ts:
        m_dt = datetime.fromisoformat(m_ts.replace("Z", "+00:00"))
        if cutoff_48h <= m_dt < cutoff_24h:
            merged_prev.append(p)

print(f"\n=== COMPARISON WITH PREVIOUS 24H ({cutoff_48h.isoformat()} to {cutoff_24h.isoformat()}) ===")
print(f"Previous PRs Opened: {len(opened_prev)}")
print(f"Previous PRs Merged: {len(merged_prev)}")
